for n in range(7,14):
 ts=list(itertools.combinations(range(n),4));qs=list(itertools.combinations(range(n),3));es=list(itertools.combinations(range(n),2))
 X={t:z3.Bool('x_'+str(t)) for t in ts};Y={q:z3.Bool('y_'+str(q)) for q in qs}
